import { NeonWidget } from './neon-widget';
import { insertBefore, updateConditionalElements, useElementIf, useElementIfElse } from './dom-manipulation';
export class NeonWidgetSlotted extends NeonWidget {
    static get requiredSlots() {
        return [];
    }
    /**
     * In PDS-4561, we made slots a public property.  When using neon, it's a performance
     * bonus to set the slots using the slots property instead of passing in the slotted elements
     * as children.
     */
    set slots(value) {
        //Mark all nodes as isProcessedByNeon
        for (const node of Object.values(value)) {
            node.isProcessedByNeon = true;
        }
        //merge the externally set slots into the private _slots Record.
        Object.assign(this._slots, value);
        //Update Conditional Elements after processing just like we did in the mutation observer.
        updateConditionalElements(this);
    }
    get slots() {
        return this._slots;
    }
    constructor() {
        super();
        //Elements marked with data-slot="XX" will be stored in this hash map.
        this._slots = {};
        //Any content passed into the widget that is not marked as a slot will be stored in this array for later use if needed.
        this.nonSlottedNodes = [];
        this.nonSlottedNodesEndMarker = document.createComment('neon-non-slotted-nodes-end-marker');
        //Let's create the mutation observer here.
        this.slotMutationObserver = this.createSlotMutationObserver();
    }
    /**
    * Extracts widget children that have a data-slot attributes for reference/placement when widgets are being built.
    */
    extractSlots() {
        for (const node of this.childNodes) {
            if (node.nodeType === Node.ELEMENT_NODE) {
                const slotName = node.getAttribute('data-slot');
                if (slotName != null) {
                    this.slots[String(slotName)] = node;
                    continue;
                }
            }
            //If the node is not an Element or it is an element and is not a slot, then we save it off as a non-slotted node.
            this.nonSlottedNodes.push(node);
        }
    }
    getSlot(slotName) {
        return useElementIf(() => { return this.slots[slotName] != null; }, () => { return this.slots[slotName]; });
    }
    /**
     * Use this function if you need an element to show up when the slot does not exist.
     * @param slotName The name of the slot to get.
     * @param getElseElement A function that gets the element to show if the slot does not exist.
     * @returns Array of two ConditionalElement objects
     */
    getSlotElse(slotName, getElseElement) {
        return useElementIfElse(() => { return this.slots[slotName] != null; }, () => { return this.slots[slotName]; }, getElseElement);
    }
    slotExists(slotName) {
        return this.slots[slotName] != null;
    }
    getNonSlottedNodes() {
        return [
            ...this.nonSlottedNodes,
            this.nonSlottedNodesEndMarker
        ];
    }
    connectedCallback() {
        if (!this.isInitialized) {
            //This is the first time that the widget has hit the DOM.
            //It will only be called ONCE throughout the lifecycle of the neon-widget.
            this.extractSlots();
        }
        //NOTE: This function is called in this position of the function on purpose.
        // - After the slot extraction
        // - before turning on the slot observer
        super.connectedCallback();
        //Setting up the observer to only look at direct children.
        this.slotMutationObserver.observe(this, { childList: true });
    }
    disconnectedCallback() {
        this.slotMutationObserver.disconnect();
    }
    createSlotMutationObserver() {
        return new MutationObserver((mutationRecords) => {
            let newSlotCount = 0;
            for (const mutationRecord of mutationRecords) {
                const addedNodes = mutationRecord.addedNodes;
                for (let i = 0; i < addedNodes.length; i++) {
                    const node = addedNodes.item(i);
                    if (node instanceof HTMLElement) {
                        if (node.isProcessedByNeon) {
                            //skip nodes that have already been processed by neon
                            continue;
                        }
                        //First check to see if it's a slot
                        const element = node;
                        const slotName = element.getAttribute('data-slot');
                        if (slotName != null) {
                            this.slots[slotName] = element;
                            element.remove(); //now that we have a pointer to the element, we remove it from the DOM.
                            element.isProcessedByNeon = true;
                            newSlotCount++;
                        }
                        //If it isn't a slot, then we need to add it to the non-slotted-nodes array
                        //and append it to the DOM at the end of the nonSlottedNodes
                        this.nonSlottedNodes.push(node);
                        node.isProcessedByNeon = true;
                        insertBefore(node, this.nonSlottedNodesEndMarker);
                    }
                }
            }
            if (newSlotCount > 0) {
                updateConditionalElements(this);
            }
        });
    }
    validateInputs() {
        super.validateInputs();
        //NeonWidget.requiredSlots will only ever get the empty array.
        //this.constructor.requiredSlots makes sure to get the array from the class that extends NeonWidget.
        const requiredSlots = this.constructor.requiredSlots;
        for (const requiredSlot of requiredSlots) {
            const slotNode = this.slots[requiredSlot.slot];
            if (slotNode == null) {
                if (requiredSlot.tag == null) {
                    console.error(`<${this.tagName.toLowerCase()} id="${this.getAttribute('id')} ...> requires a child tag with the data-slot="${requiredSlot.slot}"> attribute.`);
                }
                else if (requiredSlot.tag instanceof RegExp) {
                    console.error(`<${this.tagName.toLowerCase()} id="${this.getAttribute('id')} ...> requires a child tag that matches the regex ${requiredSlot.tag} with the data-slot="${requiredSlot.slot}"> attribute.`);
                }
                else {
                    console.error(`<${this.tagName.toLowerCase()} id="${this.getAttribute('id')} ...> requires a child tag '${requiredSlot.tag}' with the data-slot="${requiredSlot.slot}" attribute.`);
                }
            }
            else if (requiredSlot.tag != null) {
                if (requiredSlot.tag instanceof RegExp) {
                    if (!requiredSlot.tag.test(slotNode.nodeName.toLowerCase())) {
                        console.error(`The tag with attribute data-slot="${requiredSlot.slot}" inside of <${this.tagName.toLowerCase()} id="${this.getAttribute('id')} ...> must be a tag that matches the regex ${String(requiredSlot.tag)}.`);
                    }
                }
                else {
                    if (requiredSlot.tag !== slotNode.nodeName.toLowerCase()) {
                        console.error(`The tag with attribute data-slot="${requiredSlot.slot}" inside of <${this.tagName.toLowerCase()} id="${this.getAttribute('id')} ...> must be a "${String(requiredSlot.tag)}" tag.`);
                    }
                }
            }
        }
    }
} // End Class
